/* Compact acquisition UX. The prototype simulates trusted idle reports; production decisions belong to the server. */
const RealmDiscoveries=(()=>{
    const M=MageIdleSpells;let serial=0;
    const windowId=()=> 'idle-window-'+(++serial),def=r=>M.definitions[r],owned=r=>state.unlocked.includes(def(r).name);
    const rollsFor=(p,r,seconds)=>p.unlocked.includes(def(r).name)?0:Math.min(M.hardLimit-p.realmFinds.misses[r],Math.floor((p.realmFinds.bank[r]+seconds)/M.interval));
    const samples=(p,r,seconds)=>Array.from({length:rollsFor(p,r,seconds)},()=>Math.random());
    const nextIn=r=>{const s=M.interval-state.realmFinds.bank[r];return Math.floor(s/60)+':'+String(s%60).padStart(2,'0');};
    function trigger(r=state.realm,small=false){return `<button class="realm-find-trigger ${small?'small':''} ${state.realmFinds.unseen.includes(def(r).name)?'new-find':''}" data-discovery-realm="${r}" aria-label="${realms[r]} realm-exclusive spell. ${owned(r)?def(r).name+' discovered':Math.round(M.chance(state.realmFinds.misses[r])*100)+' percent next drop chance, '+state.realmFinds.misses[r]+' rolls without a find'}">${owned(r)?sprite(def(r).art):ui('book')}<small>${owned(r)?'✓':'Find'}</small>${state.realmFinds.unseen.includes(def(r).name)?'<b class="find-new">!</b>':''}</button>`;}
    function detail(){const r=state.modal.realm,d=def(r),has=owned(r),misses=state.realmFinds.misses[r];return `<div class="realm-find-hero">${sprite(d.art)}<div><span class="kicker">${realms[r]} IDLE · REALM EXCLUSIVE</span><h2>${d.name}</h2><p>${d.description}</p></div></div>${has?`<div class="find-owned">${glyph('check')} In your collection</div><div class="stack">${btn('Try spell','tryRealmSpell')}${btn('View spell','viewRealmSpell',true)}</div>`:`<div class="find-odds"><div><small>Next drop chance</small><strong data-find-chance>${Math.round(M.chance(misses)*100)}%</strong></div><div><small>Idle until next roll</small><strong data-find-next>${nextIn(r)}</strong></div></div><div class="find-pity"><span>Rolls without a find <b data-find-misses>${misses} / ${M.hardLimit}</b></span><div class="find-pips" role="img" aria-label="${misses} misses, guaranteed by roll ${M.hardLimit}">${Array.from({length:M.hardLimit},(_,i)=>`<i class="${i<misses?'filled':''}"></i>`).join('')}</div><strong data-find-guarantee>Guaranteed within ${M.hardLimit-misses} ${M.hardLimit-misses===1?'roll':'rolls'}</strong></div><p class="find-source">${ui(realms[r].toLowerCase(),'inline-icon')} Idle in ${realms[r]} realm · Any farming place</p><div class="stack">${btn(canVisit(r)?'Farm '+realms[r]+' realm':'Realm locked','farmRealmFind',false,!canVisit(r))}</div>`}<details class="find-rules"><summary>Drop rules</summary><p>One roll per 5 minutes of credited idle. Chance starts at 10%, increases after 6 misses and reaches 100% on roll 10.</p><p>Progress stays with each realm when you travel. Time away counts up to 12h. Extra manual kills do not add rolls.</p></details>`;}
    function open(r){state.realmFinds.unseen=state.realmFinds.unseen.filter(n=>n!==def(r).name);openModal({type:'realmDiscovery',realm:r});}
    function tick(){if(!state.idle.length)return;const r=state.realm,out=M.credit(state,{id:state.realmFindWindow+'-'+state.seconds,windowId:state.realmFindWindow,realm:r,seconds:1,samples:samples(state,r,1)});if(!out.ok)return;if(out.receipt.found.length)notify('New spell · '+out.receipt.found[0]);refresh();}
    function refresh(){for(const el of phone.querySelectorAll('[data-discovery-realm]')){const r=Number(el.dataset.discoveryRealm),temp=document.createElement('div');temp.innerHTML=trigger(r,el.classList.contains('small'));const next=temp.firstElementChild;el.className=next.className;el.innerHTML=next.innerHTML;el.setAttribute('aria-label',next.getAttribute('aria-label'));}if(state.modal?.type==='realmDiscovery'){const r=state.modal.realm;const next=phone.querySelector('[data-find-next]');if(next)next.textContent=nextIn(r);const misses=state.realmFinds.misses[r],chance=phone.querySelector('[data-find-chance]');if(chance)chance.textContent=Math.round(M.chance(misses)*100)+'%';const count=phone.querySelector('[data-find-misses]');if(count)count.textContent=misses+' / '+M.hardLimit;phone.querySelectorAll('.find-pips i').forEach((el,i)=>el.classList.toggle('filled',i<misses));const pips=phone.querySelector('.find-pips');if(pips)pips.setAttribute('aria-label',misses+' misses, guaranteed by roll '+M.hardLimit);const guarantee=phone.querySelector('[data-find-guarantee]');if(guarantee)guarantee.textContent='Guaranteed within '+(M.hardLimit-misses)+' '+(M.hardLimit-misses===1?'roll':'rolls');if(owned(r)&&phone.querySelector('.find-odds'))render(true);}}
    function prepareReturn(){const r=state.returned.realm??state.realm,seconds=Math.min(12,state.returned.hours)*3600,params={id:'return-'+(++serial),windowId:'absence-'+serial,realm:r,seconds,source:'absence',samples:samples(state,r,seconds)},copy=structuredClone(state),out=M.credit(copy,params);state.returned.realmFind={params,receipt:out.receipt};}
    function returnMarkup(){const report=state.returned?.realmFind;if(!report?.receipt?.found.length)return '';const d=def(report.receipt.realm);return `<div class="return-find">${sprite(d.art)}<div><small>${state.returnClaimed?'Discovered':'Realm spell found'}</small><strong>${d.name}</strong></div>${state.returnClaimed?glyph('check'):ui('book','inline-icon')}</div>`;}
    function claimReturn(){const report=state.returned?.realmFind;return !report||M.credit(state,report.params).ok;}
    function farm(){const r=state.modal.realm;if(visitRealm(state,r)){resetIdleAnimation();go('realm');}}
    function viewSpell(){const d=def(state.modal.realm);state.collectionTab='spells';state.build='idle';go('library');openModal({type:'card',kind:'spells',id:spells.findIndex(s=>s.name===d.name)});}
    function trySpell(){const d=def(state.modal.realm);if(owned(d.realm))ActivePlay.open(d.name);}
    return {windowId,def,trigger,detail,open,tick,refresh,prepareReturn,returnMarkup,claimReturn,farm,viewSpell,trySpell};
})();
